87:                 m_semaphore.wait(locker, [&]() { return m_resources.size() == resourceCount; });
88:             }
89:             resources = m_resources;
90:             m_resources.clear();
91:             return resources;
92:         }
93:     
94:     private:
95:         std::vector<RESOURCE_TYPE> m_resources;
96:         std::mutex m_queueLock;
97:         std::condition_variable m_semaphore;
98:         std::atomic<bool> m_shutdown;
99:     };
