102:     class CurlContainer
103:     {
104:     public:
105:         CurlContainer(unsigned maxSize = 16, long requestTimeout = 10000, long connectTimeout = 5000):
106:               maxPoolSize_(maxSize), 
107:               requestTimeout_(requestTimeout), 
108:               connectTimeout_(connectTimeout),
109:               poolSize_(0)
110:         {
111:         }
112:     
113:         ~CurlContainer()
114:         {
115:             for (CURL* handle : handleContainer_.ShutdownAndWait(poolSize_)) {
116:                 curl_easy_cleanup(handle);
117:             }
118:         }
119:     
120:         CURL* Acquire()
121:         {
122:             if(!handleContainer_.HasResourcesAvailable()) {
123:                 growPool();
124:             }
125:             CURL* handle = handleContainer_.Acquire();
126:             return handle;
127:         }    
128:     
129:         void Release(CURL* handle, bool force)
130:         {
131:             if (handle) {
132:                 curl_easy_reset(handle);
133:                 if (force) {
134:                     CURL* newhandle = curl_easy_init();
135:                     if (newhandle) {
136:                         curl_easy_cleanup(handle);
137:                         handle = newhandle;
138:                     }
139:                 }
140:                 setDefaultOptions(handle);
141:                 handleContainer_.Release(handle);
142:             }
143:         }
144:     
145:     private:
146:         CurlContainer(const CurlContainer&) = delete;
147:         const CurlContainer& operator = (const CurlContainer&) = delete;
148:         CurlContainer(const CurlContainer&&) = delete;
149:         const CurlContainer& operator = (const CurlContainer&&) = delete;
150:     
151:         bool growPool()
152:         {
153:             std::lock_guard<std::mutex> locker(containerLock_);
154:             if (poolSize_ < maxPoolSize_) {
155:                 unsigned multiplier = poolSize_ > 0 ? poolSize_ : 1;
156:                 unsigned amountToAdd = (std::min)(multiplier * 2, maxPoolSize_ - poolSize_);
157:         
158:                 unsigned actuallyAdded = 0;
159:                 for (unsigned i = 0; i < amountToAdd; ++i) {
160:                     CURL* curlHandle = curl_easy_init();
161:                     if (curlHandle) {
162:                         setDefaultOptions(curlHandle);
163:                         handleContainer_.Release(curlHandle);
164:                         ++actuallyAdded;
165:                     } else {
166:                         break;
167:                     }
168:                 }
169:                 poolSize_ += actuallyAdded;
170:                 return actuallyAdded > 0;
171:             }
172:             return false;
173:         }
174:     
175:         void setDefaultOptions(CURL* handle)
176:         {
177:             curl_easy_setopt(handle, CURLOPT_NOSIGNAL, 1L);
178:             curl_easy_setopt(handle, CURLOPT_TCP_NODELAY, 1);
179:             curl_easy_setopt(handle, CURLOPT_NETRC, CURL_NETRC_IGNORED);
180: 
181:             curl_easy_setopt(handle, CURLOPT_TIMEOUT_MS, 0L);
182:             curl_easy_setopt(handle, CURLOPT_CONNECTTIMEOUT_MS, connectTimeout_);
183:             curl_easy_setopt(handle, CURLOPT_LOW_SPEED_LIMIT, 1L);
184:             curl_easy_setopt(handle, CURLOPT_LOW_SPEED_TIME, requestTimeout_ / 1000);
185: 
186:             curl_easy_setopt(handle, CURLOPT_SSL_VERIFYPEER, 0L);
187:             curl_easy_setopt(handle, CURLOPT_SSL_VERIFYHOST, 0L);
188:         }
189:     
190:     private:
191:         ResourceManager_<CURL*> handleContainer_;
192:         unsigned maxPoolSize_;
193:         unsigned long requestTimeout_;
194:         unsigned long connectTimeout_;
195:         unsigned poolSize_;
196:         std::mutex containerLock_;
197:     };
