351:     static int progressCallback(void *userdata, double dltotal, double dlnow,  double ultotal, double ulnow)
352:     {
353:         UNUSED_PARAM(dltotal);
354:         UNUSED_PARAM(dlnow);
355:         UNUSED_PARAM(ultotal);
356:         UNUSED_PARAM(ulnow);
357:         TransferState *state = static_cast<TransferState*>(userdata);
358:         if (state == nullptr || state->owner == nullptr) {
359:             return 0;
360:         }
361: 
362:         CurlHttpClient *thiz = static_cast<CurlHttpClient *>(state->owner);
363: 
364:         //stop by upper caller
365:         if (!thiz->isEnable()) {
366:             return 1;
367:         }
368: 
369:         //for speed update
370:         if (thiz->sendRateLimiter_ != nullptr) {
371:             auto rate = thiz->sendRateLimiter_->Rate();
372:             if (rate != state->sendSpeed) {
373:                 state->sendSpeed = rate;
374:                 auto speed = static_cast<curl_off_t>(rate);
375:                 speed = speed * 1024;
376:                 curl_easy_setopt(state->curl, CURLOPT_MAX_SEND_SPEED_LARGE, speed);
377:             }
378:         }
379: 
380:         if (thiz->recvRateLimiter_ != nullptr) {
381:             auto rate = thiz->recvRateLimiter_->Rate();
382:             if (rate != state->recvSpeed) {
383:                 state->recvSpeed = rate;
384:                 auto speed = static_cast<curl_off_t>(rate);
385:                 speed = speed * 1024;
386:                 curl_easy_setopt(state->curl, CURLOPT_MAX_RECV_SPEED_LARGE, speed);
387:             }
388:         }
389: 
390:         return 0;
391:     }
