393:     bool static ignoreHeader(const std::string& header, const std::string expect)
394:     {
395:         if ((expect.length() == header.length()) &&
396:             std::equal(header.begin(), header.end(), expect.begin(),
397:                 [](char a, char b) {return ::tolower(a) == ::tolower(b); })) {
398:             return true;
399:         }
400:         return false;
401:     }
402: }
