459:     // Disable Expect: 100-continue
460:     list = curl_slist_append(list, "Expect:");
461: 
462:     auto response = std::make_shared<HttpResponse>(request);
463:     
464:     std::iostream::pos_type requestBodyPos = -1;
465:     if (request->Body() != nullptr) {
466:         requestBodyPos = request->Body()->tellg();
467:     }
468: 
469:     CURL * curl = curlContainer_->Acquire();
470: 
471:     OSS_LOG(LogLevel::LogDebug, TAG, "request(%p) acquire curl handle:%p", request.get(), curl);
472: 
473:     uint64_t initCRC64 = 0;
474: #ifdef ENABLE_OSS_TEST
475:     if (headers.find("oss-test-crc64") != headers.end()) {
476:         initCRC64 = std::strtoull(headers.at("oss-test-crc64").c_str(), nullptr, 10);
477:     }
478: #endif
479:     TransferState transferState = {
480:         this,
481:         curl,
482:         request.get(),
483:         response.get(),
484:         0, -1, 
485:         true, -1, 
486:         request->TransferProgress().Handler,
487:         request->TransferProgress().UserData,
488:         request->hasCheckCrc64(), initCRC64, initCRC64, 
489:         0, 0
490:     };
491: 
492:     int64_t contentlength = -1;
493:     if (request->hasHeader(Http::CONTENT_LENGTH)) {
494:         transferState.total = std::atoll(request->Header(Http::CONTENT_LENGTH).c_str());
495:         contentlength = transferState.total;
496:     }
497: 
498:     std::string url = request->url().toString();
499:     curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
500:     switch (request->method())
501:     {
502:     case Http::Method::Head:
503:         curl_easy_setopt(curl, CURLOPT_NOBODY, 1);
504:         break;
505:     case Http::Method::Put:
506:         curl_easy_setopt(curl, CURLOPT_UPLOAD, 1L);
507:         if (contentlength < 0) {
508:             // if nobody, set it to 0
509:             if (request->Body() == nullptr) {
510:                 curl_off_t uploadsize = 0;
511:                 curl_easy_setopt(curl, CURLOPT_INFILESIZE_LARGE, uploadsize);
512:             }
513:         }
514:         else {
515:             if (!request->chunkedEncoding()) {
516:                 curl_off_t uploadsize = static_cast<curl_off_t>(contentlength);
517:                 curl_easy_setopt(curl, CURLOPT_INFILESIZE_LARGE, uploadsize);
518:             }
519:         }
520:         break;
521:     case Http::Method::Post:
522:         curl_easy_setopt(curl, CURLOPT_POST, 1L);
523:         if (contentlength < 0) {
524:             // if nobody, set it to 0
525:             if (request->Body() == nullptr) {
526:                 curl_off_t length_of_data = 0;
527:                 curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE_LARGE, length_of_data);
528:             }
529:         }
530:         else {
531:             if (!request->chunkedEncoding()) {
532:                 curl_off_t length_of_data  = static_cast<curl_off_t>(contentlength);
533:                 curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE_LARGE, length_of_data);
534:             }
535:         }		
