547:     curl_easy_setopt(curl, CURLOPT_HTTPHEADER, list);
548:     curl_easy_setopt(curl, CURLOPT_HEADERDATA, &transferState);
549:     curl_easy_setopt(curl, CURLOPT_HEADERFUNCTION, recvHeaders);
