572:         curl_easy_setopt(curl, CURLOPT_PROXYPORT, (long) proxyPort_);
573:         curl_easy_setopt(curl, CURLOPT_PROXYUSERNAME, proxyUserName_.c_str());
574:         curl_easy_setopt(curl, CURLOPT_PROXYPASSWORD, proxyPassword_.c_str());
575:     }
