577:     if (!networkInterface_.empty()) {
578:         curl_easy_setopt(curl, CURLOPT_INTERFACE, networkInterface_.c_str());
579:     }
580: 
581:     //debug
582:     if (GetLogLevelInner() >= LogLevel::LogInfo) {
583:         curl_easy_setopt(curl, CURLOPT_VERBOSE, 1L);
584:         curl_easy_setopt(curl, CURLOPT_DEBUGFUNCTION, debugCallback);
