617:     CURLcode res = curl_easy_perform(curl);
618:     long response_code= 0;
619:     curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
620: 
621:     if (res == CURLE_OK) {
622:         response->setStatusCode(response_code);
623:     } else {
624:         response->setStatusCode(res + ERROR_CURL_BASE);
625:         switch (res) {
