static std::string to_datetime_string(const std::chrono::system_clock::time_point tp)
{
    auto tt = std::chrono::system_clock::to_time_t(tp);
    struct tm tm;
    char date[60] = { 0 };
#ifdef _WIN32
    localtime_s(&tm, &tt);
    sprintf_s(date, "%d-%02d-%02d %02d:%02d:%02d",
